AULAS["CPfBy3XS3rw"] = aula_en(
    "Dizer só <i>I like</i> e <i>I don't like</i> funciona, mas soa repetitivo. Há uma escala inteira entre amar e odiar: <i>I'm crazy about</i>, <i>I'm into</i>, <i>I don't mind</i>, <i>I can't stand</i>. Com ela, você expressa exatamente o quanto gosta de algo.",
    ["usar a escala de gostos do mais forte ao mais fraco;", "usar <i>I'm into</i> e <i>I'm not a big fan of</i>;", "usar <i>I can't stand</i> com cuidado."],
    ("O que significa “I don't mind waiting”?", ["Eu odeio esperar.", "Não me importo de esperar.", "Eu não espero."], 1,
     ["Seria <i>I hate waiting</i>.", "Isso! <i>I don't mind</i> é o meio da escala: tanto faz, não me incomoda.", "Não é isso."],
     "<i>I don't mind</i> = não me incomoda."),
    ("Gostos musicais", [
        ("Sam", "Are you into jazz?", "Você curte jazz?"),
        ("Duda", "Not really. I'm not a big fan of jazz. I'm crazy about rock!", "Não muito. Não sou muito fã de jazz. Sou louca por rock!"),
        ("Sam", "I don't mind rock, but I can't stand heavy metal.", "Não me importo com rock, mas não suporto heavy metal."),
        ("Duda", "Really? I love it!", "Sério? Eu amo!"),
    ]),
    "as expressões de gostar e não gostar, da mais forte à mais fraca",
    tabela("A escala", ["Expressão", "Intensidade"], [
        ["I love / I'm crazy about", "❤❤❤ amo"], ["I really like / I'm into", "❤❤ gosto muito / curto"], ["I like", "❤ gosto"],
        ["I don't mind", "😐 não me incomoda"], ["I don't like / I'm not a big fan of", "👎 não gosto muito"], ["I hate / I can't stand", "👎👎 odeio / não suporto"],
    ], corpo="<p>Todas são seguidas de substantivo ou verbo-ing: <i>I can't stand waiting</i>.</p>"),
    [("I'm crazy about", "sou louco por", "I'm crazy about pizza."), ("I'm into", "eu curto", "I'm into photography."), ("I don't mind", "não me importo", "I don't mind working late."),
     ("I'm not a big fan of", "não sou muito fã de", "I'm not a big fan of horror movies."), ("I can't stand", "não suporto", "I can't stand traffic."), ("Not really.", "Não muito.", "Do you like it? Not really.")],
    [("I can't stand traffic.", ["Não suporto trânsito", "Gosto de trânsito", "Não me importo com trânsito"], 0, "Não suporto trânsito."),
     ("I'm into photography.", ["Curto fotografia", "Odeio fotografia", "Sou fotógrafo"], 0, "Curto fotografia."),
     ("I don't mind working late.", ["Odeio trabalhar tarde", "Não me importo de trabalhar até tarde", "Nunca trabalho tarde"], 1, "Não me importo de trabalhar até tarde."),
     ("I'm crazy about pizza.", "4 palavras (contando a contração)"), ("Not really.", "2 palavras")],
    [("I'm crazy about soccer.", "Sou louco por futebol."), ("I'm not a big fan of spicy food.", "Não sou muito fã de comida apimentada."), ("I don't mind waiting.", "Não me importo de esperar."), ("I can't stand loud music.", "Não suporto música alta.")],
    [("<i>I don't mind to wait.</i>", "<i>I don't mind waiting.</i> (com -ing)"), ("Usar <i>I hate</i> para tudo.", "Em contexto profissional, <i>I'm not a big fan of</i> é mais educado."), ("<i>I'm crazy for</i>.", "A forma comum é <i>crazy <b>about</b></i>.")],
    "<p>Em discussões técnicas, opiniões aparecem suavizadas: <b>I'm not a big fan of this approach</b>, <b>I don't mind either option</b>, <b>I'm really into Rust lately</b>. Saber a escala ajuda a discordar com educação.</p>",
    [("Mais forte:", ["I don't mind", "I'm crazy about", "I like"], 1, "Topo da escala."),
     ("Forma educada de dizer que não gosta:", ["I can't stand it.", "I'm not a big fan of it.", "I hate it."], 1, "Suaviza."),
     ("Complete: “I don't mind ___.”", ["to cook", "cooking", "cook"], 1, "-ing.")],
    ["Escala: crazy about → into → like → don't mind → not a big fan → can't stand.", "Todas + substantivo ou verbo-ing.", "Prefira as formas suaves no trabalho."],
    "Aula 09: small talk.", "I'm not a big fan of")

