    [("Confundir <i>say</i> e <i>tell</i>.", "<i>Tell</i> pede a pessoa: <i>tell <b>me</b></i>; <i>say</i> não: <i>say hello</i>."), ("Confundir <i>know</i> (saber) e <i>meet</i> (conhecer pessoa pela primeira vez).", "<i>Nice to meet you</i>, não <i>nice to know you</i>."), ("Traduzir “tomar uma decisão” como <i>take a decision</i>.", "No inglês americano é <i>make a decision</i>.")],
    "<p>Em tecnologia: <b>It works on my machine.</b> / <b>Try restarting the server.</b> / <b>I need to make a change.</b> / <b>Can you take a look?</b> / <b>Let me know</b> (me avise) é das frases mais comuns em e-mails.</p>",
